use vstd::prelude::*;

verus! {

fn imag(val: Vec<(f64, f64)>) -> (out: Vec<f64>)
    ensures
        // same length
        out.len() == val.len(),

        // pointwise: output[i] is imag part of input[i]
        forall|i: int|
            0 <= i < val.len() ==> out[i] == val[i].1,

        // if imag part is 0.0 then output is 0.0
        forall|i: int|
            0 <= i < val.len() ==> (val[i].1 == 0.0 ==> out[i] == 0.0),

        // if input complex number is not (0.0, 0.0), output is still imag part
        forall|i: int|
            0 <= i < val.len() ==> ((val[i].0 != 0.0 || val[i].1 != 0.0) ==> out[i] == val[i].1),
{
    let n = val.len();
    let mut out: Vec<f64> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n
        invariant
            0 <= i <= n,
            out.len() == i,
            forall|j: int| 0 <= j < i ==> out[j] == val[j].1,
        decreases n - i,
    {
        // read-only access to val
        let im: f64 = val[i].1;
        out.push(im);

        // establish the new element’s relationship
        assert(out[i as int] == val[i as int].1);

        i = i + 1;
    }

    out
}

} // verus!

